WITH with_windows AS (SELECT id, discount_pct, NTILE(10) OVER (PARTITION BY channel ORDER BY discount_pct, id) AS discount_pct_bucket, ROW_NUMBER() OVER (PARTITION BY promo_code ORDER BY ends_on DESC, id) AS seq_no FROM promotions) SELECT seq_no, ROUND(AVG(discount_pct), 2) AS avg_discount_pct, COUNT(*) AS event_count FROM with_windows GROUP BY seq_no HAVING event_count > 1 ORDER BY event_count DESC
